  @Test public void coldSportsRoutingPreservesApprovedModeDecisionWithoutForcedPro()throws Exception{for(String saved:new String[]{"focus","compact"}){reset();assertEquals("mobile",get(a,"mCobraGuideStyle"));h.prefs.edit().putString("guide_view_mode",saved).commit();call(a,"cobraSelectDrawerOwner","SPORTS");assertEquals(saved.equals("focus"),call(a,"cobraProSportsRoutingEnabled"));assertEquals(false,call(a,"cobraProPlayerSportsEnabled"));call(a,"showCobraPrimaryView");measure();assertEquals(false,get(a,"mCobraProActive"));assertNull(get(a,"mCobraProHeroUi"));if(saved.equals("focus")){assertEquals("mobile",get(a,"mCobraGuideStyle"));assertTrue(((View)get(a,"mCobraGuideShell")).isAttachedToWindow());}else assertEquals("COBRA • SPORTS",get(a,"mCobraStageTitle"));}}
@Test public void mutedPreviewPipIsVisibleAndDoesNotOverlapOriginalControlsAtAllowedSizes()throws Exception{for(int[] size:new int[][]{{412,915},{915,412},{720,840},{840,720},{280,280}}){resetAt(size[0],size[1]);context("pro_non_sports");assertTrue(h.hero().right.performClick());h.freshPlayer();Object channel=call(a,"cobraProCurrentChannel");put(a,"mGuidePreviewChannel",channel);put(a,"mCobraPreviewPlayer",h.player);put(a,"mCobraPreviewSessionKey",call(a,"cobraChannelKey",channel));assertTrue(h.hero().preview.performClick());h.f.frames(20);WindowInsets insets=new WindowInsets.Builder().setInsets(WindowInsets.Type.systemBars(),android.graphics.Insets.of(8,24,8,24)).setInsetsIgnoringVisibility(WindowInsets.Type.systemBars(),android.graphics.Insets.of(8,24,8,24)).build();a.getWindow().getDecorView().dispatchApplyWindowInsets(insets);h.f.measure(a,size[0],size[1]);assertWindow(size[0],size[1]);CobraProUi.Hero hero=h.hero();assertEquals(CobraProUi.PREVIEW,hero.state);Rect pip=new Rect(),unmute=new Rect(),status=new Rect();assertTrue(hero.previewPip.getGlobalVisibleRect(pip));assertEquals(48,pip.width());assertEquals(48,pip.height());assertTrue(hero.unmute.getGlobalVisibleRect(unmute));assertTrue(hero.status.getGlobalVisibleRect(status));assertFalse(Rect.intersects(pip,unmute));assertFalse(Rect.intersects(pip,status));assertEquals((hero.getWidth()-124)/2,hero.unmute.getLeft());assertEquals(hero.getWidth()-12-64,hero.status.getLeft());assertTrue(hero.previewPip.stack);captureCurrent("corrective-preview-pip-"+size[0]+"x"+size[1]);assertEquals("PiP",CobraProUi.fit(hero.previewPip.label,hero.previewPip.p,hero.previewPip.getWidth()-4*hero.getResources().getDisplayMetrics().density));int before=PipBoundary.calls;float x=hero.previewPip.getLeft()+24,y=hero.previewPip.getTop()+24;long now=android.os.SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0),up=MotionEvent.obtain(now,now+40,MotionEvent.ACTION_UP,x,y,0);try{assertTrue(hero.dispatchTouchEvent(down));assertTrue(hero.dispatchTouchEvent(up));}finally{down.recycle();up.recycle();}h.f.frames(4);assertEquals(before+1,PipBoundary.calls);assertSame(h.player,get(a,"mPlayer"));assertFalse(h.state.released);assertEquals(0,h.state.prepares);}}
  @Test public void proExitEntryAndFullscreenBackRebuildActualHierarchy()throws Exception{for(String mode:new String[]{"mobile","compact","cards","grid"}){reset();context("pro_sports");mode(mode);contextMini();fullscreen(false);noSports(false);click(chrome(),"Return to preview");measure();assertNull(get(a,"mPlayerOverlay"));assertEquals(mode,get(a,"mCobraGuideStyle"));View returned=(View)get(a,"mCobraGuideShell");if("mobile".equals(mode)){assertNotNull(returned);assertTrue(returned.isAttachedToWindow());assertNull(returned.findViewWithTag("cobra_pro_hero_overlay"));}else{assertNull(returned);assertEquals("COBRA • SPORTS",get(a,"mCobraStageTitle"));assertNotNull(a.getWindow().getDecorView().findViewWithTag("cobra_sports_drawer_header"));}CobraCorrectiveRoutingReferenceTest.assertReference("return_"+mode,CobraCorrectiveRoutingReferenceTest.state(h));mode("focus");assertEquals(true,get(a,"mCobraProActive"));assertNotNull(get(a,"mCobraProHeroUi"));}}
  @Test @Config(shadows=ShadowActivity.class) public void actualActivityRecreationRetainsDirtyMobilePreferenceIsolation()throws Exception{
    ActivityController<InfinityLiveActivity> controller=Robolectric.buildActivity(InfinityLiveActivity.class).setup();InfinityLiveActivity real=controller.get();
    try{SharedPreferences prefs=(SharedPreferences)get(real,"mPrefs");((List)get(real,"mChannels")).addAll((List)get(a,"mChannels"));put(real,"mCobraPreviewAutoplayAllowed",false);call(real,"cobraSwitchMode","focus");call(real,"cobraSwitchMode","mobile");assertEquals("focus",prefs.getString("guide_view_mode",""));h.f.measure(real,412,915);controller.windowFocusChanged(true);assertTrue(real.getWindow().getDecorView().isAttachedToWindow());controller.recreate();real=controller.get();((List)get(real,"mChannels")).addAll((List)get(a,"mChannels"));put(real,"mCobraPreviewAutoplayAllowed",false);call(real,"showCobraPrimaryView");h.f.measure(real,412,915);assertEquals("mobile",get(real,"mCobraGuideStyle"));assertEquals(false,call(real,"cobraProPlayerSportsEnabled"));assertNull(get(real,"mCobraProHeroUi"));h.freshPlayer();Object channel=((List)get(real,"mChannels")).get(0);put(real,"mGuidePreviewChannel",channel);put(real,"mCobraPreviewPlayer",h.player);put(real,"mCobraPreviewSessionKey",call(real,"cobraChannelKey",channel));call(real,"promoteCobraPreviewToFullscreen",channel);h.f.measure(real,412,915);View rebuilt=(View)get(real,"mPlayerChrome");assertNotNull(rebuilt);assertTrue(rebuilt.isAttachedToWindow());assertNotNull(rebuilt.findViewWithTag("cobra_fullscreen_pip"));assertNull(rebuilt.findViewWithTag("cobra_pro_fullscreen_controls"));assertNull(rebuilt.findViewWithTag("cobra_fullscreen_stats"));assertNull(get(real,"mCobraScoreTicker"));assertFalse(controls(rebuilt).contains("Stats"));assertFalse(controls(rebuilt).contains("Status"));View channels=h.f.description(rebuilt,"Channels");assertNotNull(channels);assertTrue(channels.performClick());h.f.measure(real,412,915);assertNull(((View)get(real,"mCobraPlayerDrawer")).findViewWithTag("cobra_player_tab_SPORTS"));}finally{controller.pause().stop().destroy();}
  }
